// Package ws is the WebSocket layer: connections, sessions (who is on the
// other end), the protocol frames and per-action acknowledgements.
//
// The protocol is mirrored in client/src/api/protocol.ts; change both together.
package ws

import "encoding/json"

// Message types sent by the server.
const (
	TypeAck             = "ACK"
	TypeNack            = "NACK"
	TypeTimeSync        = "TIME_SYNC"
	TypeSessionReplaced = "SESSION_REPLACED"
)

// Action is a client → server frame. ID is generated by the client; the
// server answers every action that has one with ACK or NACK, and a repeated
// ID is acknowledged again without being applied twice.
type Action struct {
	ID      string          `json:"id"`
	Type    string          `json:"type"`
	Payload json.RawMessage `json:"payload"`
	// ClientTime is when the action was made, in server time as estimated by
	// the device (device clock + offset). Offline marks an action that was
	// queued or resent after a lost connection (§3, §9).
	ClientTime int64 `json:"client_time,omitempty"`
	Offline    bool  `json:"offline,omitempty"`
}

// Frame is a server → client message. Every frame carries the server time.
// State frames carry a sequence number; a client ignores a state frame older
// than the one it has.
type Frame struct {
	Type       string `json:"type"`
	Payload    any    `json:"payload"`
	ServerTime int64  `json:"server_time"`
	Seq        int64  `json:"seq,omitempty"`
}

type AckPayload struct {
	ID string `json:"id"`
}

type NackPayload struct {
	ID     string `json:"id"`
	Reason string `json:"reason"`
}

type SessionReplacedPayload struct {
	Reason string `json:"reason"`
}

// Roles a connection can have; chosen by the page the device opened.
type Role string

const (
	RoleOperator Role = "operator"
	RoleJudge    Role = "judge"
	RoleViewer   Role = "viewer"
)

// Session describes who is on the other end of a connection.
type Session struct {
	Role   Role
	Seat   int    // 1–3 for judges
	Device string // stable per browser; only used to log takeovers by another device
}
